#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n;
    if (!(std::cin >> n)) return 1;
    std::vector<int> v(n);
    for (int i = 0; i < n; i++) std::cin >> v[i];

    std::sort(v.begin(), v.end());
    for (size_t i = 0; i < v.size(); i++) {
        std::cout << v[i];
        if (i + 1 < v.size()) std::cout << " ";
    }
    std::cout << "\n";
    return 0;
}
